#
# t_phase7_reference.jl
#
# Point-wise comparison of the Phase 7 algorithms with the NESSi reference
# data test/nessi/data/phase7_fourier.dat and phase7_ness.dat (generated by
# .nessi/kbref/phase7_fourier_ref.cpp and phase7_ness_ref.cpp; the inputs
# below are the same closed-form definitions as in the generators).
#
# Tolerances: FFT and the corrected DFT atol = rtol = 1e-12, all the other
# results atol = rtol = 1e-10 for every record. The quick profile consumes a
# fixed subset of the records of every component, the release profile all
# records.
#
# NESSi Catch tests that are not ported (non-HDF5 parts are ported to
# test/basic/t_ness.jl and t_ness_utils.jl):
#   * all [hdf5] sections (ness2_fft_array_basic.cpp:104-159,
#     ness2_herm_matrix_ness_basic.cpp:276-), KB does not support HDF5;
#   * assertions on C++ copy constructors and memory management, which have
#     no Julia counterpart;
#   * ness2_omp_manager.cpp is ported in Phase 8 (P8-W4-T8,
#     test/basic/t_threads.jl, FFT plan cache thread contract).
#
# Deviation: force_equilibrium of NESSi 2.0.0 returns -1 times the physical
# lesser component; KB uses the physical sign, so the lesser records of
# `force_equilibrium` are compared with -1 times the reference.
#

isdefined(Main, :kb_test_profile) ||
    include(joinpath(@__DIR__, "..", "common", "profile.jl"))
isdefined(Main, :read_kbref) || include(joinpath(@__DIR__, "common.jl"))

using Test
using LinearAlgebra
using KadanoffBaym

const P7_DATA = joinpath(@__DIR__, "data")

# Compare the KB values with the reference rows. `kbval(row)` returns the
# KB value. The failures are reported with the component and the indices.
function p7_compare(rows, kbval; atol, rtol, sgn = r -> 1.0)
    fails = String[]
    for r in rows
        x = kbval(r)
        y = sgn(r) * r.value
        isapprox(x, y; atol = atol, rtol = rtol) ||
            push!(fails, "$(r.component) ($(r.i), $(r.j), $(r.a), $(r.b)): kb = $x, nessi = $y")
    end
    isempty(fails) || println("phase7 reference failures:\n  ", join(first(fails, 10), "\n  "))
    return fails
end

# Records consumed by the profile: all records in release, otherwise a
# fixed subset of every component (no component is skipped)
function p7_select(rows)
    kb_release() && return rows
    sel = filter(r -> r.j % 17 == 0 || r.j in (1, 2, 3), rows)
    for c in Set(r.component for r in rows)
        any(r -> r.component == c, sel) || push!(sel, first(filter(r -> r.component == c, rows)))
    end
    return sel
end

@testset verbose = true "KadanoffBaym: Phase 7 NESSi reference" begin

    @testset "phase7_fourier" begin
        ref = read_kbref(joinpath(P7_DATA, "phase7_fourier.dat"))
        rows = ref.rows
        comps = Set(r.component for r in rows)
        @test comps == Set(KBREF_COMPONENTS["phase7_fourier"])

        # FFT
        fftval = Dict{Tuple{String,Int},Vector{ComplexF64}}()
        for N in (2, 3, 4, 5, 6, 10, 12, 16, 25, 60, 97, 101)
            x = [complex(cos(0.3n + 0.1N), sin(0.7n * n / N)) for n = 0:N-1]
            fftval[("fft_input", N)] = x
            fftval[("fft_forward", N)] = fft(x, FFT_FORWARD)
            fftval[("fft_backward", N)] = fft(x, FFT_BACKWARD)
        end
        @test Set(r.i for r in rows if r.component == "fft_input") ==
              Set((2, 3, 4, 5, 6, 10, 12, 16, 25, 60, 97, 101))
        r_fft = filter(r -> startswith(r.component, "fft"), rows)
        @test isempty(p7_compare(r_fft, r -> fftval[(r.component, r.i)][r.j+1];
                                 atol = 1e-12, rtol = 1e-12))

        # Correction factors
        θs = (0.0, 1e-8, -1e-8, 0.049999, -0.049999, 0.050001, -0.050001, 0.7)
        function dftcorr(r)
            θ = θs[r.i+1]
            r.a == 0 && return complex(θ)
            corfac, endcor = r.j == 1 ? get_dftcorr_linear(θ) : get_dftcorr_cubic(θ)
            return r.a == 1 ? complex(corfac) : endcor[r.a-1]
        end
        r_cor = filter(r -> r.component == "dftcorr", rows)
        @test length(r_cor) == 8 * (4 + 6)
        @test isempty(p7_compare(r_cor, dftcorr; atol = 1e-12, rtol = 1e-12))

        # Corrected and adaptive Fourier integrals
        funcs = ((x -> complex(1.0), 0.0, 1.0), (x -> complex(exp(-x)), 0.0, 2.0),
                 (x -> complex(exp(-x^2)), -5.0, 5.0))
        ωs = (-3.0, -0.7, 0.0, 0.5, 2.3, 10.0)
        function adaptive(r)
            f, lo, hi = funcs[r.i+1]
            ω = ωs[r.j+1]
            r.a == 0 && return complex(ω)
            if r.a == 1
                vals = [f(lo + (hi - lo) * k / 32) for k = 0:32]
                return dft_cplx(ω, lo, hi, vals)[1]
            end
            return adft_func(f, ω, lo, hi; n = 20, limit = 40)[1]
        end
        r_ad = filter(r -> r.component == "adaptive", rows)
        @test length(r_ad) == 3 * 6 * 3
        @test isempty(p7_compare(filter(r -> r.a ≤ 1, r_ad), adaptive; atol = 1e-12, rtol = 1e-12))
        @test isempty(p7_compare(filter(r -> r.a == 2, r_ad), adaptive; atol = 1e-10, rtol = 1e-10))

        # Matsubara Fourier transforms
        mats(τ) = ComplexF64[-0.6exp(-0.4τ) 0.2cos(1.3τ)+0.05im*τ;
                             0.2cos(1.3τ)-0.05im*τ -0.3exp(0.25τ)]
        mdft = Dict{Int,Array{ComplexF64,3}}()
        mft = Dict{Tuple{Int,Int},Matrix{ComplexF64}}()
        for c = 0:1
            sign = c == 0 ? FERMI : BOSE
            β = 2.5
            G = ℱ(Cn(2, 21, 2, 2, 1.0, β), sign)
            for r = 0:20
                G.mat[r+1] = mats(r * β / 20)
            end
            raw = zeros(ComplexF64, 21, 2, 2)
            matsubara_dft!(raw, G.mat, sign)
            mdft[c] = raw
            for order in (0, 1, 3), m in (-25, -3, -1, 0, 1, 2, 7, 30)
                dest = zeros(ComplexF64, 2, 2)
                matsubara_ft!(dest, m, G.mat, raw, sign, β; order = order)
                mft[(10c + order, m)] = dest
            end
        end
        r_md = filter(r -> r.component == "matsubara_dft_result", rows)
        @test length(r_md) == 2 * 21 * 4
        @test isempty(p7_compare(p7_select(r_md), r -> mdft[r.i][r.j+1, r.a+1, r.b+1];
                                 atol = 1e-12, rtol = 1e-12))
        r_mf = filter(r -> r.component == "matsubara_ft_result", rows)
        @test length(r_mf) == 2 * 3 * 8 * 4
        @test isempty(p7_compare(r_mf, r -> mft[(r.i, r.j)][r.a+1, r.b+1]; atol = 1e-10, rtol = 1e-10))

        # Fourier Matsubara VIE2, pcf = 20 (NESSi default) and pcf = 10
        vF(τ) = 0.4 * ComplexF64[exp(-0.5τ) 0.1+0.05im*τ; 0.1-0.05im*τ exp(-1.2τ)]
        vQ(τ) = ComplexF64[-exp(-0.3τ) 0.05; 0.05 -0.5exp(0.2τ)]
        vie = Dict{Tuple{String,Int},ℱ}()
        for c = 0:1, pcf in (20, 10)
            sign = c == 0 ? FERMI : BOSE
            β = 3.0
            C = Cn(2, 41, 2, 2, 1.0, β)
            F, Q, X = ℱ(C, sign), ℱ(C, sign), ℱ(C, sign)
            for r = 0:40
                F.mat[r+1] = vF(r * β / 40)
                Q.mat[r+1] = vQ(r * β / 40)
            end
            KadanoffBaym._vie2_mat_fourier!(X, F, Q, β; pcf = pcf, order = 3)
            vie[("vie2_pcf$pcf", c)] = X
        end
        vieval(r) = vie[(r.component, r.i)].mat[r.j+1][r.a+1, r.b+1]
        r_v = filter(r -> startswith(r.component, "vie2_"), rows)
        @test length(r_v) == 2 * 2 * 41 * 4
        @test isempty(p7_compare(p7_select(r_v), vieval; atol = 1e-10, rtol = 1e-10))
        # Counterexample: pcf = 10 does not reproduce the NESSi pcf = 20 result
        r20 = filter(r -> r.component == "vie2_pcf20", rows)
        @test maximum(r -> abs(vie[("vie2_pcf10", r.i)].mat[r.j+1][r.a+1, r.b+1] - r.value), r20) > 1e-10
    end

    @testset "phase7_ness" begin
        ref = read_kbref(joinpath(P7_DATA, "phase7_ness.dat"))
        rows = ref.rows
        nftmax = parse(Int, ref.metadata["nft_max"])
        @test nftmax == 512
        @test Set(r.component for r in rows) == Set(KBREF_COMPONENTS["phase7_ness"])

        Nft, h, β = 256, 0.05, 5.0
        g = NessGrid(Nft, h)
        NG(d) = NessHermMat(g, d)

        # Equilibrium Green's functions
        G0, G1, G2, G3 = NG(1), NG(1), NG(1), NG(1)
        from_dos_ness!(G0, FERMI, GaussianDOS(0.0, 1.0), β, 0.3)
        from_dos_ness!(G1, FERMI, BetheDOS(-2.0, 2.0), β, 0.1)
        from_dos_ness!(G2, FERMI, GaussianDOS(0.0, 1.0), β, 0.3;
                                method = FFT_ADAPTIVE, limit = 100, nn = 20)
        from_dos_ness!(G3, BOSE, BetheDOS(1.0, 5.0), β, 0.0)

        # Dyson equations
        S = deepcopy(G1)
        smul!(S, 0.25, FFT_TIME)
        G4 = NG(1)
        dyson_ness!(G4, 0.0, fill(ComplexF64(0.2), 1, 1), S; bath_type = BATH_GAUSS,
                    bath_eta = 0.1, bath_beta = β, bath_mu = 0.0)
        S5 = NG(2)
        for n = 1:Nft
            r0, r1 = G0.ret.time[1, 1, n], G1.ret.time[1, 1, n]
            l0, l1 = G0.les.time[1, 1, n], G1.les.time[1, 1, n]
            S5.ret.time[:, :, n] = [0.3r0 0.1r0; 0.1r0 0.2r1]
            S5.les.time[:, :, n] = [0.3l0 0.1l0; 0.1l0 0.2l1]
        end
        G5 = NG(2)
        dyson_ness!(G5, 0.0, ComplexF64[0.3 0.2im; -0.2im -0.4], S5; bath_type = BATH_CONST,
                    bath_eta = 0.05, bath_beta = β, bath_mu = 0.0)
        G6 = NG(1)
        dyson_ness!(G6, 0.0, fill(ComplexF64(0.4), 1, 1), NG(1); bath_type = BATH_OHMIC,
                    bath_eta = 0.1, bath_beta = β, bath_mu = 0.0)
        G7 = NG(1)
        dyson_ness!(G7, 0.0, zeros(ComplexF64, 1, 1), S)
        cases = (G0, G1, G2, G3, G4, G5, G6, G7)

        function gfval(r)
            G = cases[r.i+1]
            A = startswith(r.component, "ret") ? G.ret : G.les
            D = endswith(r.component, "time") ? A.time : A.freq
            return D[r.a+1, r.b+1, r.j+1]
        end
        r_gf = filter(r -> r.component in ("ret_time", "les_time", "ret_freq", "les_freq"), rows)
        @test Set(r.i for r in r_gf) == Set(0:7)
        # The adaptive case 2 has no frequency data
        @test !any(r -> r.i == 2 && endswith(r.component, "freq"), r_gf)
        @test isempty(p7_compare(p7_select(r_gf), gfval; atol = 1e-10, rtol = 1e-10))

        # Bath self-energies
        baths = (BATH_NONE, BATH_CONST, BATH_GAUSS, BATH_OHMIC)
        function bathval(r)
            ret, les = sigma_bath(-3.0 + 0.25r.j, h, baths[r.i+1], 0.2, β, 0.1)
            return r.component == "bath_ret" ? ret : les
        end
        r_b = filter(r -> startswith(r.component, "bath_"), rows)
        @test length(r_b) == 2 * 4 * 25
        @test isempty(p7_compare(r_b, bathval; atol = 1e-10, rtol = 1e-10))

        # Density matrices
        dens = Dict(i => density_matrix(cases[i+1], FERMI) for i in (0, 1, 4, 5))
        cdens = Dict(0 => convolution_density_matrix(G0, G1, FERMI),
                     1 => convolution_density_matrix(G5, G5, FERMI))
        r_d = filter(r -> r.component == "density", rows)
        @test Set(r.i for r in r_d) == Set((0, 1, 4, 5))
        @test isempty(p7_compare(r_d, r -> dens[r.i][r.a+1, r.b+1]; atol = 1e-10, rtol = 1e-10))
        r_cd = filter(r -> r.component == "convolution_density", rows)
        @test length(r_cd) == 1 + 4
        @test isempty(p7_compare(r_cd, r -> cdens[r.i][r.a+1, r.b+1]; atol = 1e-10, rtol = 1e-10))
        # Aggregate check with the Catch tolerance (after the point-wise test)
        @test all(r -> abs(real(dens[r.i][r.a+1, r.b+1]) - real(r.value)) < 1e-6, r_d)

        # Operations, time domain: ret at j = n, les at j = nft_max + n
        function timeval(G::NessHermMat, r)
            n = r.j < nftmax ? r.j : r.j - nftmax
            A = r.j < nftmax ? G.ret : G.les
            return A.time[r.a+1, r.b+1, n+1]
        end
        B1, B2 = NG(1), NG(1)
        bubble1_ness!(B1, G0, G1)
        bubble2_ness!(B2, G0, G1)
        D1, D2 = NG(2), NG(2)
        for a = 1:2, b = 1:2
            bubble1_ness!(D1, a, b, G5, a, b, G0, 1, 1)
            bubble2_ness!(D2, a, b, G5, a, b, G0, 1, 1)
        end
        ops = Dict(("bubble1", 0) => B1, ("bubble2", 0) => B2,
                   ("bubble1", 1) => D1, ("bubble2", 1) => D2,
                   ("resample", 0) => downsample(G0, 4), ("resample", 1) => upsample(G1, 2))
        for (i, (sign, dos, μ)) in enumerate(((FERMI, GaussianDOS(0.0, 1.0), 0.3),
                                              (BOSE, GaussianDOS(3.0, 0.5), -1.0)))
            F = NG(1)
            from_dos_ness!(F, sign, dos, β, μ)
            F.les.time .= 0
            F.les.freq .= 0
            equilibrate_lesser!(F, sign, β, μ)
            ops[("force_equilibrium", i - 1)] = F
        end
        Gc = ℱ(Cn(129, 51, 1, 1, 128h, β), FERMI)
        dos = GaussianDOS(0.0, 1.0)
        from_dos!(Gc, dos, dos.lo, dos.hi, β, h; μ = 0.3, limit = 100, nn = 20)
        N0 = NG(1)
        cntr2ness!(N0, Gc, 129)
        Gc2 = ℱ(Cn(138, 51, 1, 1, 137h, β), FERMI)
        ness2cntr!(Gc2, G0)
        N1 = NG(1)
        cntr2ness!(N1, Gc2, 138)
        ops[("cntr_conversion", 0)] = N0
        ops[("cntr_conversion", 1)] = N1

        opcomps = ("bubble1", "bubble2", "resample", "force_equilibrium", "cntr_conversion")
        r_op = filter(r -> r.component in opcomps, rows)
        @test Set((r.component, r.i) for r in r_op) == Set(keys(ops))
        # The resampled grids have 64 and 512 points
        @test count(r -> r.component == "resample" && r.i == 0, r_op) == 2 * 64
        @test count(r -> r.component == "resample" && r.i == 1, r_op) == 2 * 512
        # force_equilibrium: KB uses the physical sign of the lesser component
        sgn(r) = (r.component == "force_equilibrium" && r.j ≥ nftmax) ? -1.0 : 1.0
        @test isempty(p7_compare(p7_select(r_op), r -> timeval(ops[(r.component, r.i)], r);
                                 atol = 1e-10, rtol = 1e-10, sgn = sgn))
    end

    @testset "phase7 release: all records" begin
        if kb_release()
            @test ENV["KB_TEST_PROFILE"] == "release"
            # The testsets above consumed all records in the release profile
            rs = [KbrefRow("x", 0, 5, 0, 0, 0im), KbrefRow("x", 0, 6, 0, 0, 0im)]
            @test p7_select(rs) === rs
        else
            @test kb_test_profile() == "quick"
        end
    end
end
